import random, z3
from verification import cex_minimizer as M
from spacer_verifier import verify_transition_system

NAMES = ['a', 'b', 'c']

def rnd_system(rng):
    iv = {n: rng.randint(-2, 2) for n in NAMES}
    def init(s): return z3.And(*[s[n] == iv[n] for n in NAMES])
    gk = rng.randint(0, 3); gc = rng.randint(-3, 6); gv = rng.choice(NAMES)
    coef = {n: [rng.randint(-2, 2) for _ in range(4)] for n in NAMES}
    coef2 = {n: [rng.randint(-2, 2) for _ in range(4)] for n in NAMES}
    branch = rng.random() < 0.5
    def guard(s):
        if gk == 0: return s[gv] < gc
        if gk == 1: return s[gv] <= gc
        if gk == 2: return s[gv] != gc
        return z3.BoolVal(True)
    def upd(s, n, cs):
        return z3.And(*[n[v] == cs[v][0]*s['a'] + cs[v][1]*s['b']
                        + cs[v][2]*s['c'] + cs[v][3] for v in NAMES])
    def trans(s, n):
        base = z3.And(guard(s), upd(s, n, coef))
        if branch:
            return z3.Or(base, z3.And(z3.Not(guard(s)), upd(s, n, coef2)))
        return base
    sk = rng.randint(0, 3); sc = rng.randint(-5, 15); sv = rng.choice(NAMES)
    def safety(s):
        if sk == 0: return s[sv] <= sc
        if sk == 1: return s['a'] + s['b'] + s['c'] <= sc
        if sk == 2: return z3.And(s['a'] <= sc, s['b'] >= -sc)
        return z3.Or(s['b'] >= -sc, s[sv] <= sc)
    return init, trans, safety

