    tally[key] = tally.get(key, 0) + 1
    if truth['status'] == 'unsafe' and res.safe:
        unsound += 1
        print("!! UNSOUND trial %d: spacer(concrete)=unsafe, CEGAR=safe" % trial)
    if truth['status'] == 'safe' and not res.safe and not res.exhausted:
        # CEGAR claims a real cex on a system spacer proves safe -> validator bug
        print("!! FALSE ALARM trial %d: spacer(concrete)=safe, CEGAR cex=%r" % (trial, res.cex))
        v = M.CEXValidator(NAMES).validate(res.cex, init, trans, safety)
        print("   revalidate:", v)
print("tally (concrete_truth, cegar):", tally)
print("UNSOUND:", unsound)
