import random, z3, traceback
from verification import cex_minimizer as M
from spacer_verifier import verify_transition_system

def as_list(f, names):
    def w(*vs): return f(*[dict(zip(names, v)) for v in vs])
    return w

# (A) why did spacer reject the free-constant system?
def init(s): return z3.And(s['x'] == 0, s['y'] == 0)
def trans(s, n):
    inp = z3.Int('inp')
    return z3.And(z3.Or(inp == 0, inp == 1), n['x'] == s['x'] + inp,
                  n['y'] == s['y'] + 1 - inp)
def safety(s): return z3.Or(s['x'] != 1, s['y'] != 1)
out = verify_transition_system("f", [z3.IntSort()]*2, as_list(init,['x','y']),
                               as_list(trans,['x','y']), as_list(safety,['x','y']))
print("A:", out['status'], "|", out['reason'])

# (B) incomplete var_names -> where does it blow up?
def init2(s): return z3.And(s['x'] == 0, s['z'] == 0)
def trans2(s, n): return z3.And(n['x'] == s['x'] + s['z'], n['z'] == s['z'])
def safety2(s): return s['x'] <= 3
print("B: collect_var_names =", M.collect_var_names(init2, trans2, safety2))
try:
    M.CEGARLoop(init2, trans2, safety2, var_names=['x'])
    print("B: constructed OK")
except Exception as exc:
    tb = traceback.format_exc().strip().splitlines()
    print("B: raised %s: %s" % (type(exc).__name__, exc))
    print("B: at", tb[-3].strip(), "|", tb[-2].strip())

# (C) over-approximation check across a random sweep
NAMES = ['a','b']
class Checked(M.CEGARLoop):
    bad = 0
    def _verify_abstraction(self):
        c = M._env(self.var_names, "$c"); n = M._env(self.var_names, "$n")
        s = z3.Solver()
        s.add(z3.Not(z3.Implies(self.trans_rel(c, n),
                                self.abstraction.abstract_trans()(c, n))))
        if s.check() != z3.unsat:
            Checked.bad += 1
            print("   !! not an over-approximation, kept=%s" % sorted(self.abstraction.kept))
        return M.CEGARLoop._verify_abstraction(self)

rng = random.Random(99)
checks = 0
for t in range(40):
    iv = {k: rng.randint(-2, 2) for k in NAMES}
    gc = rng.randint(-3, 6); gv = rng.choice(NAMES); gk = rng.randint(0, 2)
    co = {k: [rng.randint(-2, 2) for _ in range(3)] for k in NAMES}
    co2 = {k: [rng.randint(-2, 2) for _ in range(3)] for k in NAMES}
    branch = rng.random() < 0.5
    sc = rng.randint(-4, 12); sv = rng.choice(NAMES); sk = rng.randint(0, 2)
    def init3(s, iv=iv): return z3.And(*[s[k] == iv[k] for k in NAMES])
    def guard(s, gk=gk, gv=gv, gc=gc):
        return s[gv] < gc if gk == 0 else (s[gv] != gc if gk == 1 else z3.BoolVal(True))
    def upd(s, n, cs): return z3.And(*[n[k] == cs[k][0]*s['a'] + cs[k][1]*s['b'] + cs[k][2]
                                       for k in NAMES])
    def trans3(s, n, co=co, co2=co2, branch=branch):
        base = z3.And(guard(s), upd(s, n, co))
        return z3.Or(base, z3.And(z3.Not(guard(s)), upd(s, n, co2))) if branch else base
    def safety3(s, sk=sk, sv=sv, sc=sc):
        if sk == 0: return s[sv] <= sc
        if sk == 1: return z3.And(s['a'] <= sc, s['b'] >= -sc)
        return z3.Or(s['a'] + s['b'] <= sc, s[sv] >= -sc)
    r = Checked(init3, trans3, safety3, var_names=NAMES, horizon=4, max_iterations=8).run()
    checks += 1
    if r.cex is not None:
        v = M.CEXValidator(NAMES).validate(r.cex, init3, trans3, safety3)
        assert v.is_real, (t, v)
        assert r.cex.length <= r.original_cex.length, t
print("C: %d systems checked, over-approximation violations = %d;"
      " every reported cex re-validated real and no longer than the original"
      % (checks, Checked.bad))
